sys_script_client.script:
function onLoad() {

    try {
        var gr = new GlideAjax('x_938076_now_utils.getIpConfigResponse');
        gr.addParam('sysparm_name', 'highlightIPFields');
        gr.getXMLAnswer(getFieldNames);

        function getFieldNames(response) {

            var getFields = JSON.parse(response);
            g_form.addInfoMessage('results ' + JSON.parse(response));

            g_form.addErrorMessage('Hello 123 ' + getFields.length)

            getFields.forEach(function(fields){

                g_form.addErrorMessage('Field Name ' + fields);
                var refField2 = g_form.getControl(fields);
                refField2.style.backgroundColor = 'yellow';

            });


    };
} catch (ex) {
    g_form.addErrorMessage('Error ' + ex);

}


}
